'use client';

import { useMemo } from 'react';
import { useApp } from '@/hooks/use-app';
import type { Service } from '@/types';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { DollarSign } from 'lucide-react';
import { format } from 'date-fns';
import { arSA } from 'date-fns/locale';

export function Dashboard() {
  const { t, language, services } = useApp();

  const reportData = useMemo(() => {
    let totalSales = 0;
    services.forEach(service => {
      totalSales += service.price;
    });
    return { totalSales };
  }, [services]);

  const getServiceTypeName = (s: Service) => {
    const name = language === 'ar' ? s.serviceNameAr : s.serviceNameEn;
    return s.waxAddOn ? `${name} + ${t('wax-add-on')}` : name;
  };

  return (
    <div className="text-white space-y-6">
      <h1 className="text-3xl font-bold">{t('dashboard-title')}</h1>
      
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Fake Bar Chart to match the design */}
        <Card className="lg:col-span-2 bg-gray-900 border-gray-700">
          <CardHeader>
            <CardTitle>{t('sales-activity-title')}</CardTitle>
          </CardHeader>
          <CardContent className="flex items-end h-64">
            {/* Placeholder for bar chart visuals */}
            <div className="flex items-end justify-around w-full h-full text-xs text-gray-400">
                <div className="text-center"><div className="bg-blue-500 w-8 h-3/5 rounded-t-sm mx-auto"></div><span>Jan</span></div>
                <div className="text-center"><div className="bg-blue-500 w-8 h-2/5 rounded-t-sm mx-auto"></div><span>Feb</span></div>
                <div className="text-center"><div className="bg-blue-500 w-8 h-4/5 rounded-t-sm mx-auto"></div><span>Mar</span></div>
                <div className="text-center"><div className="bg-blue-500 w-8 h-full rounded-t-sm mx-auto"></div><span>Apr</span></div>
                <div className="text-center"><div className="bg-blue-500 w-8 h-2/3 rounded-t-sm mx-auto"></div><span>May</span></div>
                <div className="text-center"><div className="bg-blue-500 w-8 h-1/2 rounded-t-sm mx-auto"></div><span>Jun</span></div>
            </div>
          </CardContent>
        </Card>

        {/* Summary Cards */}
        <div className="space-y-6">
          <Card className="bg-gray-900 border-gray-700">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">{t('todays-sales-label')}</CardTitle>
              <DollarSign className="h-4 w-4 text-gray-400" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{reportData.totalSales.toFixed(2)} {t('sar')}</div>
              <p className="text-xs text-gray-400">{t('sales-summary-desc')}</p>
            </CardContent>
          </Card>
          <Card className="bg-gray-900 border-gray-700">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">{t('washes-completed-label')}</CardTitle>
            </CardHeader>
            <CardContent>
                <div className="text-2xl font-bold">{services.length}</div>
                <p className="text-xs text-gray-400">{t('washes-summary-desc')}</p>
            </CardContent>
          </Card>
           <Card className="bg-gray-900 border-gray-700">
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">{t('inventory-status-title')}</CardTitle>
            </CardHeader>
            <CardContent>
                <div className="text-lg font-bold text-red-500">{t('out-of-stock-label')}</div>
                <p className="text-xs text-gray-400">{t('inventory-summary-desc')}</p>
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Recent Sales Table */}
      <Card className="bg-gray-900 border-gray-700">
        <CardHeader>
          <CardTitle>{t('recent-sales-title')}</CardTitle>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow className="border-gray-700 hover:bg-gray-800">
                <TableHead className="text-white">{t('table-header-service')}</TableHead>
                <TableHead className="text-white">{t('table-header-status')}</TableHead>
                <TableHead className="text-right text-white">{t('table-header-price')}</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {services.slice(0, 5).map((s: Service) => (
                <TableRow key={s.id} className="border-gray-700 hover:bg-gray-800">
                  <TableCell>
                    <div className="font-medium">{getServiceTypeName(s)}</div>
                    <div className="text-sm text-gray-400">{format(new Date(s.timestamp), 'p', { locale: language === 'ar' ? arSA : undefined })}</div>
                  </TableCell>
                  <TableCell>
                    <span className={`px-2 py-1 rounded-full text-xs ${s.isPaid ? 'bg-green-500/20 text-green-400' : 'bg-yellow-500/20 text-yellow-400'}`}>
                      {s.isPaid ? t('payment-status-paid') : t('payment-status-not-paid')}
                    </span>
                  </TableCell>
                  <TableCell className="text-right">{s.price.toFixed(2)} {t('sar')}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  );
}
